// --- SCHEMA & TYPES ---



export type MomentumCutoffProps = Record<string, any>;

// --- COMPONENT ---

const MomentumCutoff: React.FC<MomentumCutoffProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  iconCount = 120,
  primaryIconColor = "#ffffff",
  secondaryIconColor = "#ff3b30",
  tertiaryIconColor = "#007aff",
  momentumCutoffTime = 0.5,
  gravityStrength = 2.5,
  upwardVelocity = 35,
}) => {

  useFontLoader(["Inter"]); // Basic loader compliance

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Calculate specific frames
  const cutoffFrame = Math.floor(durationInSeconds * fps * momentumCutoffTime);

  // Memoize particle data to keep it stable across frames
  const particles = React.useMemo(() => {
    return new Array(iconCount).fill(0).map((_, i) => {
      const seed = i * 782.34;
      
      // Properties
      const type = Math.floor(random(seed) * 3); // 0, 1, 2
      const x = random(seed + 1) * width;
      const size = interpolate(random(seed + 2), [0, 1], [30, 90]); // 30px to 90px
      const velocityVariance = interpolate(random(seed + 3), [0, 1], [0.5, 1.5]); 
      const startYOffset = interpolate(random(seed + 4), [0, 1], [0, height]); // Stagger start positions
      const rotation = random(seed + 5) * 360;
      
      // Color selection
      const colorSeed = random(seed + 6);
      let color = primaryIconColor;
      if (colorSeed > 0.6) color = secondaryIconColor;
      if (colorSeed > 0.85) color = tertiaryIconColor;

      return {
        id: i,
        type,
        x,
        size,
        baseVelocity: upwardVelocity * velocityVariance,
        startY: height + size + startYOffset, // Start below screen + stagger
        color,
        rotation,
      };
    });
  }, [iconCount, width, height, upwardVelocity, primaryIconColor, secondaryIconColor, tertiaryIconColor]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {particles.map((p) => {
        // --- PHYSICS SIMULATION ---
        
        // 1. Upward Phase
        // y = startY - velocity * frame
        // This is a linear motion (constant momentum)
        const upwardY = p.startY - p.baseVelocity * frame;

        // 2. Cutoff Point Calculation
        // Where was this specific particle at the exact moment of cutoff?
        const yAtCutoff = p.startY - p.baseVelocity * cutoffFrame;

        // 3. Downward Phase (Gravity)
        // y = yAtCutoff + 0.5 * gravity * (timeSinceCutoff)^2
        const framesSinceCutoff = frame - cutoffFrame;
        const gravityDrop = 0.5 * gravityStrength * (framesSinceCutoff * framesSinceCutoff);
        const downwardY = yAtCutoff + gravityDrop;

        // 4. Decision
        const currentY = frame < cutoffFrame ? upwardY : downwardY;

        // Optimization: Don't render if completely off-screen (with buffer)
        const isOffScreen = currentY > height + 200 || currentY < -200;
        // However, during the rush, they might be above screen (-200) waiting to fall back down.
        // We only cull if they are way below the screen.
        if (currentY > height + 300) return null;

        // Icon Rendering
        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: p.x,
              top: currentY,
              width: p.size,
              height: p.size,
              transform: `rotate(${p.rotation}deg)`,
              opacity: 1,
            }}
          >
            {p.type === 0 && <HeartIcon color={p.color} />}
            {p.type === 1 && <EyeIcon color={p.color} />}
            {p.type === 2 && <MessageIcon color={p.color} />}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default MomentumCutoff;